cat > /tmp/a.py <<'E'
import ast,sys,glob
for f in sorted(glob.glob('billing/*.py')):
    t=ast.parse(open(f).read())
    def walk(n,pre):
        for c in ast.iter_child_nodes(n):
            if isinstance(c,(ast.FunctionDef,ast.AsyncFunctionDef)):
                rets=[]
                def r(x):
                    for y in ast.iter_child_nodes(x):
                        if isinstance(y,(ast.FunctionDef,ast.Lambda,ast.ClassDef)):continue
                        if isinstance(y,ast.Return):rets.append(y)
                        r(y)
                r(c)
                vals=[ast.unparse(x.value) if x.value else 'BARE' for x in rets]
                last=c.body[-1]
                print(f"{pre}{c.name}: nret={len(rets)} lastRet={isinstance(last,ast.Return)} {vals}")
                walk(c,pre+c.name+'.')
            elif isinstance(c,ast.ClassDef): walk(c,pre+c.name+'.')
    print('==',f);walk(t,'')
E
.venv/bin/python /tmp/a.py | grep -v "nret=0"
